// Block 1: Deterministic E.164 Phone & Email Hygiene (Includes realistic sample payload when triggered from Node 00)
const rawInput = $input.first().json.body || $input.first().json || {};
const isEmptyTrigger = Object.keys(rawInput).length === 0;

const body = isEmptyTrigger ? {
  name: 'Tunde Bakare',
  email: 'Tunde.Bakare@LagosFintech.ng',
  phone: '08031234567',
  company: 'Lagos Fintech Ltd',
  notes: 'Looking for paid media ROAS scaling and CRM automation ($3,500/mo budget).',
  source: 'Webform / Meta Lead Ad'
} : rawInput;

const rawPhone = String(body.phone || '08031234567').replace(/[^0-9+]/g, '');
let e164Phone = rawPhone;
if (rawPhone.startsWith('0') && rawPhone.length === 11) {
  e164Phone = '+234' + rawPhone.slice(1);
} else if (!rawPhone.startsWith('+') && rawPhone.length >= 10) {
  e164Phone = '+' + rawPhone;
}

return [{
  json: {
    lead_id: `LEAD-${Date.now()}`,
    full_name: String(body.name || 'Unknown Lead').trim(),
    email: String(body.email || '').trim().toLowerCase(),
    phone_e164: e164Phone,
    whatsapp_url: e164Phone ? `https://wa.me/${e164Phone.replace('+', '')}` : '',
    company: String(body.company || '').trim(),
    inquiry_notes: String(body.notes || body.message || '').trim(),
    source: String(body.source || 'webform').trim(),
    received_at: new Date().toISOString()
  }
}];

