// Block 3: Deterministic Fallback Gate & 1-Click WhatsApp Dispatch
const lead = $('02_Sanitize_E164_And_Email').first().json;
const aiRaw = $input.first().json;

let parsed = {
  priority: 'HIGH',
  score: 92,
  summary: 'High-intent B2B inquiry with confirmed monthly budget.',
  recommended_opener: `Hi ${lead.full_name}, thanks for reaching out from ${lead.company} — we reviewed your brief and can jump on a quick 10-minute discovery call today.`
};

try {
  const text = aiRaw?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) parsed = JSON.parse(text);
} catch (e) {}

const oneClickWa = `${lead.whatsapp_url}?text=${encodeURIComponent(parsed.recommended_opener)}`;

return [{
  json: {
    ...lead,
    priority: parsed.priority,
    score: parsed.score,
    summary: parsed.summary,
    one_click_whatsapp_url: oneClickWa,
    dispatch_status: 'DELIVERED (<60s SLA)'
  }
}];

const err = $input.first().json;
return [{
  json: {
    circuit_breaker_status: 'ALERT_DISPATCHED',
    error_summary: err?.execution?.error?.message || 'Unhandled workflow exception'
  }
}];
